(7323261, 1142747, 114969, '<td valign="top">Given your pregnancy, I really, really hope that this is a composite! ;-) Congratulations Samantha, outstanding entry, I love it. The concept is perfect: efficient visually, very funny, and you perfectly organized everything on the canvas to make it a pleasure to look at.</td>', 'Given your pregnancy, I really, really hope that this is a composite! ;-) Congratulations Samantha, outstanding entry, I love it. The concept is perfect: efficient visually, very funny, and you perfectly organized everything on the canvas to make it a pleasure to look at.', '2015-03-04 08:45:45.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7323273, 1142559, 66267, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Paul:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Lydia:</b></div><hr/><i> I''m not at all into the whole lesbian thing, but the colors and light here are gorgeous.   9 </i></td></tr></table> <br/> <br/>I thank you for your generous vote but I certainly don''t see any ''lesbian thing'' going on here. It''s just an extension of one figure nude into two figure nudes - it was the continuation of form, and in this case function, we were after. It''s a tricky modelling feat to give great shapes under load like this. Some from this short set had more interesting angled poses but this one had the best ''lightbulb'' hand and gave emphasis to the challenge theme. I could have done a similar shot clothed - it would have been different but probably still effective; it''s just not how it worked out within the wider set, but I don''t think the nudity (within the depicted context) says anything about sexual orientation. Why would it? </i></td></tr></table> <br/> <br/>yeah, seriously...</td>', 'Originally posted by Paul: Originally posted by Lydia: I''m not at all into the whole lesbian thing, but the colors and light here are gorgeous.   9   I thank you for your generous vote but I certainly don''t see any ''lesbian thing'' going on here. It''s just an extension of one figure nude into two figure nudes - it was the continuation of form, and in this case function, we were after. It''s a tricky modelling feat to give great shapes under load like this. Some from this short set had more interesting angled poses but this one had the best ''lightbulb'' hand and gave emphasis to the challenge theme. I could have done a similar shot clothed - it would have been different but probably still effective; it''s just not how it worked out within the wider set, but I don''t think the nudity (within the depicted context) says anything about sexual orientation. Why would it?   yeah, seriously...', '2015-03-04 09:09:15.000000', NULL, 0),
(7323322, 1142559, 12611, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by LanndonKane:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Paul:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Lydia:</b></div><hr/><i> I''m not at all into the whole lesbian thing, but the colors and light here are gorgeous.   9 </i></td></tr></table> <br/> <br/>I thank you for your generous vote but I certainly don''t see any ''lesbian thing'' going on here. It''s just an extension of one figure nude into two figure nudes - it was the continuation of form, and in this case function, we were after. It''s a tricky modelling feat to give great shapes under load like this. Some from this short set had more interesting angled poses but this one had the best ''lightbulb'' hand and gave emphasis to the challenge theme. I could have done a similar shot clothed - it would have been different but probably still effective; it''s just not how it worked out within the wider set, but I don''t think the nudity (within the depicted context) says anything about sexual orientation. Why would it? </i></td></tr></table> <br/> <br/>yeah, seriously... </i></td></tr></table> <br/> <br/>In a sense, I believe you and agree with you Paul. These are women models, nudes, and although there is undeniable overt sexuality to the photograph,   there is nothing to suggest lesbianism, no stereotypes, no modern love scene of a shot: simply art- or to prudes, "candy photography."<br/><br/><i>Message edited by author 2015-03-04 10:47:04.</i></td>', 'Originally posted by LanndonKane: Originally posted by Paul: Originally posted by Lydia: I''m not at all into the whole lesbian thing, but the colors and light here are gorgeous.   9   I thank you for your generous vote but I certainly don''t see any ''lesbian thing'' going on here. It''s just an extension of one figure nude into two figure nudes - it was the continuation of form, and in this case function, we were after. It''s a tricky modelling feat to give great shapes under load like this. Some from this short set had more interesting angled poses but this one had the best ''lightbulb'' hand and gave emphasis to the challenge theme. I could have done a similar shot clothed - it would have been different but probably still effective; it''s just not how it worked out within the wider set, but I don''t think the nudity (within the depicted context) says anything about sexual orientation. Why would it?   yeah, seriously...   In a sense, I believe you and agree with you Paul. These are women models, nudes, and although there is undeniable overt sexuality to the photograph,   there is nothing to suggest lesbianism, no stereotypes, no modern love scene of a shot: simply art- or to prudes, "candy photography."', '2015-03-04 10:46:36.000000', '2015-03-04 10:47:04.000000', 0),
(7323335, 1142815, 98339, '<td valign="top">I thought this was you..great job...I reallyneed to learn how you do this!!!</td>', 'I thought this was you..great job...I reallyneed to learn how you do this!!!', '2015-03-04 11:27:23.000000', NULL, 0),
(7323358, 1142559, 118154, '<td valign="top">Congratulations, this is a wonderful image. I can only think that Lydia was having an off day.</td>', 'Congratulations, this is a wonderful image. I can only think that Lydia was having an off day.', '2015-03-04 12:24:31.000000', NULL, 0),
(7323363, 1142815, 89723, '<td valign="top">Brilliant!</td>', 'Brilliant!', '2015-03-04 12:45:00.000000', NULL, 0),
(7323386, 1142559, 83149, '<td valign="top">Pleasantly surprised that this finished where it did.  <br/> <br/>It was my choice for the Red, but I thought you would have had a lot of low votes due to the nudity.  Very pleased to see that I was wrong.</td>', 'Pleasantly surprised that this finished where it did.   It was my choice for the Red, but I thought you would have had a lot of low votes due to the nudity.  Very pleased to see that I was wrong.', '2015-03-04 13:34:00.000000', NULL, 0),
(7323388, 1142815, 83149, '<td valign="top">Very well done, and even more impressive that you did it in 2 1/2 hours.</td>', 'Very well done, and even more impressive that you did it in 2 1/2 hours.', '2015-03-04 13:36:31.000000', NULL, 0),
(7323392, 1142559, 114969, '<td valign="top">The human body is definitely a fantastic world to be studied by any artist. Many already did throughout the ages, and I am glad brilliant ones still go on. Of course, such approach has been (and obviously, still is) attacked for many reasons, among which, the supposed sexual references. Of course, two nude persons doesn''t necessarily imply sex, it can be a way to find new shapes, angles, beauty. And even in the cases that actually depict a sexual situation, what would be so bad about it? Sex can be beautiful too, as a part of human life. Thanks for your continuous great work and inspiration.</td>', 'The human body is definitely a fantastic world to be studied by any artist. Many already did throughout the ages, and I am glad brilliant ones still go on. Of course, such approach has been (and obviously, still is) attacked for many reasons, among which, the supposed sexual references. Of course, two nude persons doesn''t necessarily imply sex, it can be a way to find new shapes, angles, beauty. And even in the cases that actually depict a sexual situation, what would be so bad about it? Sex can be beautiful too, as a part of human life. Thanks for your continuous great work and inspiration.', '2015-03-04 13:42:09.000000', NULL, 0),
(7323413, 1142747, 24454, '<td valign="top">No surprise here!  This is amazing, and you are a genius!</td>', 'No surprise here!  This is amazing, and you are a genius!', '2015-03-04 14:42:23.000000', NULL, 0),
(7323416, 1142559, 24454, '<td valign="top">I am so proud of how far DPC voters have come!   There was a time when anything depicting nudity would have been a very hard sell for a ribbon.  I''m so glad this one got it''s very well-deserved win!   Congratulations!</td>', 'I am so proud of how far DPC voters have come!   There was a time when anything depicting nudity would have been a very hard sell for a ribbon.  I''m so glad this one got it''s very well-deserved win!   Congratulations!', '2015-03-04 14:47:19.000000', NULL, 0),
(7323417, 1142795, 24454, '<td valign="top">I thought for sure this one would ribbon!   Soooooo close!  I contributed my best to see it win, being one of your 4 10''s.  Congratulations on the honorable mention!<br/></td>', 'I thought for sure this one would ribbon!   Soooooo close!  I contributed my best to see it win, being one of your 4 10''s.  Congratulations on the honorable mention!', '2015-03-04 14:48:18.000000', NULL, 0),
(7323448, 1142815, 109227, '<td valign="top">Great job Mark; I thought this might be yours.</td>', 'Great job Mark; I thought this might be yours.', '2015-03-04 15:19:42.000000', NULL, 0),
(7323467, 1142559, 86447, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Paul:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Lydia:</b></div><hr/><i> I''m not at all into the whole lesbian thing, but the colors and light here are gorgeous.   9 </i></td></tr></table> <br/> <br/>I thank you for your generous vote but I certainly don''t see any ''lesbian thing'' going on here. It''s just an extension of one figure nude into two figure nudes - it was the continuation of form, and in this case function, we were after. It''s a tricky modelling feat to give great shapes under load like this. Some from this short set had more interesting angled poses but this one had the best ''lightbulb'' hand and gave emphasis to the challenge theme. I could have done a similar shot clothed - it would have been different but probably still effective; it''s just not how it worked out within the wider set, but I don''t think the nudity (within the depicted context) says anything about sexual orientation. Why would it?  </i></td></tr></table> <br/> <br/>You''re welcome for the vote.  It wasn''t generous.  I vote on quality of the image and this one is well-done, as usual for you, Paul.  :D  <br/> <br/>The lesbian comment was meant to be a bit humorous... because I would never get naked and ask another naked woman to change a light bulb with me.  Ha!<br/> <br/>But, now that you''ve started the conversation, and others have joined in, I''ve studied it more in view of your words.<br/> <br/>If you take these women and flip the image in your mind... with the women now lying down on the far wall, in the exact same positioning, and they''re horizontal instead of vertical on the bed or whatever they''re standing on now... THEN what does that say?   I''d say that two women in that position were being sexual together.   Two women being sexual together makes them at least lesbian (perhaps bi-sexual... or whatever else people call themselves these days).  Right?<br/> <br/>I don''t actually care one iota about their sexual preferences... They do appear to me to be two women in sexual positions alone together.   Whatever that makes them be...   ??    :D<br/> <br/>Anyway... carry on... I didn''t mean to offend with my silly quip.   It''s a silly challenge topic and I was just being silly in response.  <br/> <br/></td>', 'Originally posted by Paul: Originally posted by Lydia: I''m not at all into the whole lesbian thing, but the colors and light here are gorgeous.   9   I thank you for your generous vote but I certainly don''t see any ''lesbian thing'' going on here. It''s just an extension of one figure nude into two figure nudes - it was the continuation of form, and in this case function, we were after. It''s a tricky modelling feat to give great shapes under load like this. Some from this short set had more interesting angled poses but this one had the best ''lightbulb'' hand and gave emphasis to the challenge theme. I could have done a similar shot clothed - it would have been different but probably still effective; it''s just not how it worked out within the wider set, but I don''t think the nudity (within the depicted context) says anything about sexual orientation. Why would it?    You''re welcome for the vote.  It wasn''t generous.  I vote on quality of the image and this one is well-done, as usual for you, Paul.  :D   The lesbian comment was meant to be a bit humorous... because I would never get naked and ask another naked woman to change a light bulb with me.  Ha! But, now that you''ve started the conversation, and others have joined in, I''ve studied it more in view of your words. If you take these women and flip the image in your mind... with the women now lying down on the far wall, in the exact same positioning, and they''re horizontal instead of vertical on the bed or whatever they''re standing on now... THEN what does that say?   I''d say that two women in that position were being sexual together.   Two women being sexual together makes them at least lesbian (perhaps bi-sexual... or whatever else people call themselves these days).  Right? I don''t actually care one iota about their sexual preferences... They do appear to me to be two women in sexual positions alone together.   Whatever that makes them be...   ??    :D Anyway... carry on... I didn''t mean to offend with my silly quip.   It''s a silly challenge topic and I was just being silly in response.   ', '2015-03-04 16:18:18.000000', NULL, 0),
(7323496, 1142815, 69324, '<td valign="top">Well done. Surreal and realistic at the same time.</td>', 'Well done. Surreal and realistic at the same time.', '2015-03-04 17:11:42.000000', NULL, 0),
(7323498, 1142559, 100393, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Lydia:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Paul:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Lydia:</b></div><hr/><i> I''m not at all into the whole lesbian thing, but the colors and light here are gorgeous.   9 </i></td></tr></table> <br/> <br/>I thank you for your generous vote but I certainly don''t see any ''lesbian thing'' going on here. It''s just an extension of one figure nude into two figure nudes - it was the continuation of form, and in this case function, we were after. It''s a tricky modelling feat to give great shapes under load like this. Some from this short set had more interesting angled poses but this one had the best ''lightbulb'' hand and gave emphasis to the challenge theme. I could have done a similar shot clothed - it would have been different but probably still effective; it''s just not how it worked out within the wider set, but I don''t think the nudity (within the depicted context) says anything about sexual orientation. Why would it?  </i></td></tr></table> <br/> <br/>You''re welcome for the vote.  It wasn''t generous.  I vote on quality of the image and this one is well-done, as usual for you, Paul.  :D  <br/> <br/>The lesbian comment was meant to be a bit humorous... because I would never get naked and ask another naked woman to change a light bulb with me.  Ha!<br/> <br/>But, now that you''ve started the conversation, and others have joined in, I''ve studied it more in view of your words.<br/> <br/>If you take these women and flip the image in your mind... with the women now lying down on the far wall, in the exact same positioning, and they''re horizontal instead of vertical on the bed or whatever they''re standing on now... THEN what does that say?   I''d say that two women in that position were being sexual together.   Two women being sexual together makes them at least lesbian (perhaps bi-sexual... or whatever else people call themselves these days).  Right?<br/> <br/>I don''t actually care one iota about their sexual preferences... They do appear to me to be two women in sexual positions alone together.   Whatever that makes them be...   ??    :D<br/> <br/>Anyway... carry on... I didn''t mean to offend with my silly quip.   It''s a silly challenge topic and I was just being silly in response. </i></td></tr></table> <br/> <br/>I wasn''t at all offended Lydia, thanks for your comments too! I always enjoy the perspective you share on my nude images.myou make me think. Sometimes I write what I think.<br/> <br/>Thanks again<br/> <br/>Paul</td>', 'Originally posted by Lydia: Originally posted by Paul: Originally posted by Lydia: I''m not at all into the whole lesbian thing, but the colors and light here are gorgeous.   9   I thank you for your generous vote but I certainly don''t see any ''lesbian thing'' going on here. It''s just an extension of one figure nude into two figure nudes - it was the continuation of form, and in this case function, we were after. It''s a tricky modelling feat to give great shapes under load like this. Some from this short set had more interesting angled poses but this one had the best ''lightbulb'' hand and gave emphasis to the challenge theme. I could have done a similar shot clothed - it would have been different but probably still effective; it''s just not how it worked out within the wider set, but I don''t think the nudity (within the depicted context) says anything about sexual orientation. Why would it?    You''re welcome for the vote.  It wasn''t generous.  I vote on quality of the image and this one is well-done, as usual for you, Paul.  :D   The lesbian comment was meant to be a bit humorous... because I would never get naked and ask another naked woman to change a light bulb with me.  Ha! But, now that you''ve started the conversation, and others have joined in, I''ve studied it more in view of your words. If you take these women and flip the image in your mind... with the women now lying down on the far wall, in the exact same positioning, and they''re horizontal instead of vertical on the bed or whatever they''re standing on now... THEN what does that say?   I''d say that two women in that position were being sexual together.   Two women being sexual together makes them at least lesbian (perhaps bi-sexual... or whatever else people call themselves these days).  Right? I don''t actually care one iota about their sexual preferences... They do appear to me to be two women in sexual positions alone together.   Whatever that makes them be...   ??    :D Anyway... carry on... I didn''t mean to offend with my silly quip.   It''s a silly challenge topic and I was just being silly in response.   I wasn''t at all offended Lydia, thanks for your comments too! I always enjoy the perspective you share on my nude images.myou make me think. Sometimes I write what I think. Thanks again Paul', '2015-03-04 17:14:40.000000', NULL, 0),
(7323515, 1142795, 114969, '<td valign="top">Great work with the composite, and a creative use of the available props! Congrats on the nice finish.</td>', 'Great work with the composite, and a creative use of the available props! Congrats on the nice finish.', '2015-03-04 17:49:48.000000', NULL, 0),
(7323518, 1142815, 114969, '<td valign="top">Can''t believe you achieved this so fast! Great, great work. The reflections in the bulb are awesome.</td>', 'Can''t believe you achieved this so fast! Great, great work. The reflections in the bulb are awesome.', '2015-03-04 17:51:25.000000', NULL, 0),
(7323521, 1142742, 114969, '<td valign="top">So very creative, and so funny as well! Great job, it is a pleasure to see original concepts :)</td>', 'So very creative, and so funny as well! Great job, it is a pleasure to see original concepts :)', '2015-03-04 17:53:57.000000', NULL, 0),
(7323525, 1142790, 114969, '<td valign="top">Haha, so funny Susan :) What a great idea. Also, I know that shooting cats can be a nightmare, especially when you want them to take a specific position... So my deepest congratulations for this accomplishment!</td>', 'Haha, so funny Susan :) What a great idea. Also, I know that shooting cats can be a nightmare, especially when you want them to take a specific position... So my deepest congratulations for this accomplishment!', '2015-03-04 18:03:47.000000', NULL, 0),
(7323551, 1142559, 86447, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Paul:</b></div><hr/><i>... Sometimes I write what I think.<br/> <br/> </i></td></tr></table> <br/> <br/>LOL!   LOL again.   <br/> <br/>*hugs you in a non-heterosexual way*</td>', 'Originally posted by Paul:... Sometimes I write what I think.    LOL!   LOL again.    *hugs you in a non-heterosexual way*', '2015-03-04 19:12:50.000000', NULL, 0),
